private void renderDiscover(){
        List<DealRecord> deals=db.getDeals("trusted",320);deals.sort((a,b)->Double.compare(relevance(b),relevance(a)));body.addView(discoverHeader(deals));
        if(deals.isEmpty()){body.addView(emptyState("Niente da mostrare ancora","Apri Vinted e scorri un po'. Ludo fa il resto.",R.drawable.ludo_no_results));return;}

        DealRecord best=bestStrongOffer(deals);
        if(best!=null){sectionHeader("","Per te adesso","La scelta più forte tra qualità, prezzo e contesto.",null,null);body.addView(heroDealVNext(best));}

        List<DealRecord> urgent=urgentDeals(deals);lastUrgentIds=new HashSet<>();for(DealRecord item:urgent)if(item!=null&&!TextUtils.isEmpty(item.signature))lastUrgentIds.add(item.signature);addUrgentList(limitDeals(urgent,3));

        addDealRail("","Affari migliori","Le occasioni che meritano di essere esplorate, non solo quelle più economiche.","all",limitDeals(deals,6),6);

        List<DealRecord> topRated=new ArrayList<>(deals);topRated.sort((a,b)->{int x=Double.compare(b.rating==null?0:b.rating,a.rating==null?0:a.rating);if(x!=0)return x;return Integer.compare(nz(b.voters,0),nz(a.voters,0));});addRankedRatingList(limitDeals(topRated,5));

        List<DealRecord> discounts=new ArrayList<>(deals);discounts.removeIf(d->saving(d)==null||saving(d)<=0);discounts.sort((a,b)->Integer.compare(nz(saving(b),-1),nz(saving(a),-1)));addDiscountRail(limitDeals(discounts,6));

        List<DealRecord> bundleSources=uniqueBundleSources(deals);bundleSources.removeIf(d->bundleDealsForSource(d).size()<2);if(!bundleSources.isEmpty())addBundleSpotlight(bundleSources.get(0));

        List<DealRecord> recent=new ArrayList<>(deals);recent.sort((a,b)->Long.compare(b.firstSeen,a.firstSeen));addRecentTimeline(limitDeals(recent,7));
        if(daysSinceLastObservation()>=3)body.addView(staleCard());
    }
