    private DealRecord bestStrongOffer(List<DealRecord> deals){DealRecord best=null;double bs=-1e9;for(DealRecord d:deals){if(!personalDealEligible(d))continue;DealEvaluator.Evaluation e=DealEvaluator.evaluate(d);if(!e.discoverable())continue;double s=relevance(d)+(ageMinutes(d)<=30?7:0);if(s>bs){bs=s;best=d;}}return best;}
