    private void openCatalogPreset(String preset){String requested=TextUtils.isEmpty(preset)?"all":preset;urgentSnapshot=null;if("recent_hot".equals(requested)){urgentSnapshot=lastUrgentIds==null?new HashSet<>():new HashSet<>(lastUrgentIds);if(lastUrgentIds==null)for(DealRecord d:urgentDeals(db.getDeals("all",320)))urgentSnapshot.add(d.signature);}catalogPreset="recent_hot".equals(requested)?"recent_hot":"bundle".equals(requested)?"bundle":"all";filterMode="all";languageFilter=linkFilter=typeFilter="all";catalogMinRatingFilter=null;catalogMinDiscountFilter=null;maxPriceFilter=null;filterShipping=filterBundle=filterVerify=false;query="";if("recent_hot".equals(requested)||"recent".equals(requested))sort="recent";else if("top_rated".equals(requested))sort="bgg";else if("cheap".equals(requested))sort="price";else if("deal".equals(requested))sort="deal";else sort="relevance";openingPreset=true;try{navigate("catalog");}finally{openingPreset=false;}}


