        LinearLayout selected=new LinearLayout(this);selected.setGravity(Gravity.CENTER_VERTICAL);if(!"verified".equals(databaseScope))addFilterChip(selected,"review".equals(databaseScope)?"Da verificare":"Tutti",()->databaseScope="verified");if(databaseActiveOnly)addFilterChip(selected,"Con annunci",()->databaseActiveOnly=false);if(databaseMinRating!=null)addFilterChip(selected,"BGG "+databaseMinRating.intValue()+"+",()->databaseMinRating=null);if(databaseMaxPrice!=null)addFilterChip(selected,"≤ "+money(databaseMaxPrice),()->databaseMaxPrice=null);if(selected.getChildCount()>0){HorizontalScrollView active=new HorizontalScrollView(this);active.setHorizontalScrollBarEnabled(false);active.addView(selected);LinearLayout.LayoutParams alp=new LinearLayout.LayoutParams(-1,dp(48));alp.topMargin=dp(8);body.addView(active,alp);}

