    private Set<String> urgentSnapshot,lastUrgentIds;
    private List<DealRecord> urgentDeals(List<DealRecord> input){List<DealRecord> result=new ArrayList<>();for(DealRecord d:input){if(!personalDealEligible(d)||!DealEvaluator.evaluate(d).discoverable())continue;if(ageMinutes(d)<=60)result.add(d);}result.sort((a,b)->Double.compare(relevance(b),relevance(a)));if(result.isEmpty()){for(DealRecord d:input)if(personalDealEligible(d)&&DealEvaluator.evaluate(d).discoverable())result.add(d);result.sort((a,b)->Double.compare(relevance(b),relevance(a)));if(result.size()>8)result=new ArrayList<>(result.subList(0,8));}return result;}
    private void applyCatalogPreset(List<DealRecord>l){if("recent_hot".equals(catalogPreset)){if(urgentSnapshot!=null)l.removeIf(d->!urgentSnapshot.contains(d.signature));else{List<DealRecord> selected=urgentDeals(l);l.clear();l.addAll(selected);}}else if("bundle".equals(catalogPreset))l.removeIf(d->!hasLiveBundle(d));}
    private void applyCatalogFilter(List<DealRecord>l){if(catalogMinRatingFilter!=null)l.removeIf(d->d.rating==null||d.rating<catalogMinRatingFilter);if(catalogMinDiscountFilter!=null)l.removeIf(d->{Integer sv=saving(d);return sv==null||sv<catalogMinDiscountFilter;});if(filterShipping)l.removeIf(d->d.shippingVerifiedCents==null||d.shippingVerifiedCents>300);if(filterBundle)l.removeIf(d->!hasLiveBundle(d));if(filterVerify)l.removeIf(d->!"verify".equals(d.tier));if(maxPriceFilter!=null)l.removeIf(d->{Integer total=effectiveTotal(d);return total==null||total>maxPriceFilter;});if(!"all".equals(languageFilter))l.removeIf(d->{String code=d.languageCode==null?"":d.languageCode.toUpperCase(Locale.ROOT);return "unknown".equals(languageFilter)?!(code.isEmpty()||code.contains("?")||code.contains("DEP")):!code.contains(languageFilter);});if("linked".equals(linkFilter))l.removeIf(d->TextUtils.isEmpty(d.vintedUrl));else if("pending".equals(linkFilter))l.removeIf(d->!TextUtils.isEmpty(d.vintedUrl));else if("incomplete".equals(linkFilter))l.removeIf(d->!vintedDataIncomplete(d));else if("complete".equals(linkFilter))l.removeIf(this::vintedDataIncomplete);if(!"all".equals(typeFilter))l.removeIf(d->{String t=d.listingType==null?"":d.listingType.toLowerCase(Locale.ROOT);boolean expansion=t.contains("expan");return "expansion".equals(typeFilter)?!expansion:expansion;});}
    private boolean vintedDataIncomplete(DealRecord d){return d==null||TextUtils.isEmpty(d.vintedUrl)||TextUtils.isEmpty(d.publishedLabel)||TextUtils.isEmpty(d.sellerId);}
    private boolean vintedCoreMissing(DealRecord d){return d==null||TextUtils.isEmpty(d.vintedUrl);}
