    private void photoSearchOptions(){Dialog dialog=bottomSheet("Cerca un gioco da una foto");LinearLayout box=dialog.findViewById(SHEET_ID);box.addView(text("Inquadra bene il titolo sulla scatola.",15,MUTED,Typeface.NORMAL));Button camera=button("Scatta una foto",CYAN);camera.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_camera,0,0,0);camera.setCompoundDrawablePadding(dp(8));camera.setOnClickListener(v->{try{File folder=new File(getCacheDir(),"recognition");folder.mkdirs();File file=new File(folder,"box-"+System.currentTimeMillis()+".jpg");cameraPhoto=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".photos",file);Intent intent=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);intent.putExtra(android.provider.MediaStore.EXTRA_OUTPUT,cameraPhoto);intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);dialog.dismiss();startActivityForResult(intent,5801);}catch(Exception e){Toast.makeText(this,"Fotocamera non disponibile. Puoi scegliere una foto.",Toast.LENGTH_LONG).show();}});box.addView(camera,new LinearLayout.LayoutParams(-1,dp(52)));Button choose=button("Scegli una foto",SURFACE2);choose.setTextColor(TEXT);choose.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_gallery,0,0,0);choose.setCompoundDrawablePadding(dp(8));choose.setOnClickListener(v->{dialog.dismiss();Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.setType("image/*");pick.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(pick,5802);});box.addView(choose,new LinearLayout.LayoutParams(-1,dp(52)));dialog.show();}
